			if (w.alive[id] === 0 || w.team[id] > 1) continue;
			if (dist2(w.x[f], w.y[f], w.x[id], w.y[id]) > r2) continue;
			if (w.team[id] === team) w.hp[id] = Math.min(w.maxHp[id], w.hp[id] + applyBp(w.maxHp[id], FOUNTAIN.healBpPerSecond));
